public int findLargestSubstring(List<String> strings) {
    // Initialize the largest substring to be an empty string
    String largestSubstring = "";

    // Loop through each string in the list
    for (String str : strings) {
        // Find the length of the current string
        int strLen = str.length();

        // Loop through each position in the current string
        for (int i = 0; i < strLen; i++) {
            // Find the length of the current substring
            int currSubstrLen = 0;

            // Loop through each position in the current substring
            for (int j = i; j < strLen && j < i + currSubstrLen; j++) {
                // If the current substring is already the largest substring, break the loop
                if (currSubstrLen == largestSubstring.length()) {
                    break;
                }

                // If the current substring is a substring of the current string, increment the current substring length
                if (largestSubstring.length() < strLen && str.contains(largestSubstring)) {
                    currSubstrLen++;
                }
            }

            // If the current substring is the largest substring, update the largest substring
            if (largestSubstring.length() < strLen) {
                largestSubstring = str.substring(i, i + currSubstrLen);
            }
        }
    }

    // Return the length of the largest substring
    return largestSubstring.length();
}

