public int findLargestSubstring(List<String> strings) {
    // Step 1: Create a map to store the frequency of each character in each string
    Map<String, Map<Character, Integer>> charFrequencies = new HashMap<>();
    for (String string : strings) {
        Map<Character, Integer> stringFrequencies = new HashMap<>();
        for (int i = 0; i < string.length(); i++) {
            char c = string.charAt(i);
            stringFrequencies.put(c, stringFrequencies.getOrDefault(c, 0) + 1);
        }
        charFrequencies.put(string, stringFrequencies);
    }

    // Step 2: Create a map to store the substring frequencies of each string
    Map<String, Integer> substringFrequencies = new HashMap<>();
    for (Map.Entry<String, Map<Character, Integer>> entry : charFrequencies.entrySet()) {
        String string = entry.getKey();
        int substringLength = 1;
        while (substringLength <= string.length()) {
            Integer frequency = substringFrequencies.get(string.substring(0, substringLength));
            if (frequency == null) {
                substringFrequencies.put(string.substring(0, substringLength), 1);
            } else {
                substringFrequencies.put(string.substring(0, substringLength), frequency + 1);
            }
            substringLength++;
        }
    }

    // Step 3: Find the largest substring that is present in every string
    int largestSubstringLength = 0;
    for (Map.Entry<String, Integer> entry : substringFrequencies.entrySet()) {
        if (entry.getValue() == strings.size()) {
            largestSubstringLength = Math.max(largestSubstringLength, entry.getKey().length());
        }
    }

    return largestSubstringLength;
}

