public static int countOilDeposits(char[][] grid) {
    int count = 0;
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            if (grid[i][j] == '@') {
                count++;
                int currentX = i;
                int currentY = j;
                while (currentX >= 0 && currentX < grid.length && currentY >= 0 && currentY < grid[i].length) {
                    if (grid[currentX][currentY] == '@') {
                        grid[currentX][currentY] = '#';
                    }
                    currentX++;
                    currentY++;
                }
            }
        }
    }
    return count;
}

