public static int countOilDeposits(char[][] grid) {
    // Initialize a set to store the coordinates of all the oil deposits
    Set<String> oilDeposits = new HashSet<>();

    // Iterate through the grid
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[0].length; j++) {
            // If the current cell has oil, add its coordinates to the set
            if (grid[i][j] == '@') {
                oilDeposits.add(i + " " + j);
            }
        }
    }

    // Return the size of the set, which is the number of distinct oil deposits
    return oilDeposits.size();
}

