public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 == 1) return false;
    int[] freq = new int[k];
    for (int i = 0; i < n; i++) {
        freq[arr[i] % k]++;
    }
    for (int i = 0; i < n; i++) {
        freq[i] = freq[i] >> 1;
    }
    int count = 0;
    for (int i = 0; i < n; i++) {
        if (freq[i] > 0) count++;
    }
    return count % 2 == 0;
}

