    int[] pref = new int[n];
    int[] suf = new int[n];
    int[] count = new int[n];
    for (int i = 0; i < n; i++) {
        pref[i] = i - 1;
        suf[n - 1 - i] = i;
        count[i] = 1;
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < i; j++) {
            if (s.charAt(j) == s.charAt(i)) {
                pref[i] = Math.max(pref[j], pref[i]);
                count[i] = Math.max(count[i], count[j] + 1);
            }
        }
    }
    int res = 0;
    for (int i = 0; i < n; i++) {
        res = Math.max(res, count[i] + suf[i]);
    }
    return res;
}

