public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        result.add(i);
    }
    for (int i = 10; i <= n; i *= 10) {
        for (int j = 9; j >= 0; j--) {
            result.add(i + j);
        }
    }
    return result;
}

